export async function withLock(redis, name, fn) {
  const acquired = await redis.setNX(`lock:${name}`, '1');
  if (!acquired) throw new Error('locked');
  await redis.expire(`lock:${name}`, 10);
  try {
    return await fn();
  } finally {
    await redis.del(`lock:${name}`);
  }
}

